def transform(grid):
    from collections import defaultdict

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    by_color = defaultdict(set)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                by_color[grid[r][c]].add((r, c))

    def components(points):
        remaining = set(points)
        result = []
        while remaining:
            start = remaining.pop()
            comp = {start}
            todo = [start]
            while todo:
                r, c = todo.pop()
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        p = (r + dr, c + dc)
                        if p in remaining:
                            remaining.remove(p)
                            comp.add(p)
                            todo.append(p)
            result.append(comp)
        return result

    objects = [(color, comp) for color, pts in by_color.items()
               for comp in components(pts)]
    source_color, template = max(objects, key=lambda obj: len(obj[1]))
    minr = min(r for r, c in template)
    minc = min(c for r, c in template)
    shape = [(r - minr, c - minc) for r, c in template]

    transforms = [
        lambda r, c: (r, c), lambda r, c: (r, -c),
        lambda r, c: (-r, c), lambda r, c: (-r, -c),
        lambda r, c: (c, r), lambda r, c: (c, -r),
        lambda r, c: (-c, r), lambda r, c: (-c, -r),
    ]

    def complete(points):
        for fn in transforms:
            mapped = [fn(r, c) for r, c in shape]
            mr = min(r for r, c in mapped)
            mc = min(c for r, c in mapped)
            mapped = [(r - mr, c - mc) for r, c in mapped]
            for pr, pc in points:
                for sr, sc in mapped:
                    dr, dc = pr - sr, pc - sc
                    candidate = {(r + dr, c + dc) for r, c in mapped}
                    if points <= candidate and all(
                        0 <= r < h and 0 <= c < w for r, c in candidate
                    ):
                        return candidate
        return None

    for color, points in by_color.items():
        if color == source_color:
            continue

        # Treat separated marks as one partial copy when they jointly fit;
        # otherwise complete each distinct object independently.
        candidate = complete(points)
        if candidate is not None:
            for r, c in candidate:
                out[r][c] = color
        else:
            for comp in components(points):
                candidate = complete(comp)
                if candidate is not None:
                    for r, c in candidate:
                        out[r][c] = color

    return out
